#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT EnvironmentalSensor : 3
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1
COMPONENT Sound : 3
COMPONENT Text : 2

DEF Inl Inline {
  global TRUE
}

DEF Clock TimeSensor {
  cycleInterval 0.1
  loop TRUE
}

DEF Driver Script {
  inputOnly      SFTime   tick
  outputOnly     MFString first_url
  outputOnly     SFBool   load_out
  initializeOnly SFInt32  n 1

  url "javascript:
function tick (t) {
  n = n + 1;
  print ('driver tick ' + n);
  if (n == 3) first_url = new MFString ('lib-ext-inline.wrl');
  if (n == 4) { load_out = false; }
}
"
}

ROUTE Clock.cycleTime TO Driver.tick
ROUTE Driver.first_url TO Inl.set_url
ROUTE Driver.load_out TO Inl.set_load

